def calculate_sequence(N):
    # Initialize the sequence array (using 1-based indexing conceptually, so size N+1)
    # We need up to a_N. We will store a_1 at index 1.
    a = [0] * (N + 1)

    # Base cases
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # Recurrence: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Need a_{n-1}
        a_n_minus_1 = a[n - 1]

        # Term 1: a_{a_{n-1}}
        index1 = a_n_minus_1
        term1 = a[index1]

        # Term 2: a_{n - a_{n-1}}
        index2 = n - a_n_minus_1
        term2 = a[index2]

        a[n] = term1 + term2

    return a[1:N+1]

N_target = 10
