print(f"The first {N_target} terms are: {results}")

def calculate_a(N):
    a = {}
    a[1] = 1
    a[2] = 1
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        # We need a_{n-1} first
        if (n - 1) not in a:
            print(f"Error: a_{n-1} not calculated.")
            return {}

        an_minus_1 = a[n - 1]

        # Calculate a_{a_{n-1}} and a_{n - a_{n-1}}
        # These indices must be positive integers.
        idx1 = an_minus_1
        idx2 = n - an_minus_1

        if idx1 <= 0 or idx2 <= 0:
            print(f"Error: Indices for a_{n} are non-positive for n={n}")
            return {}

        if idx1 not in a:
            # This should not happen if the sequence is calculated sequentially
            print(f"Error: Index {idx1} for a_{n} not in calculated set.")
            return {}
        if idx2 not in a:
            # This should not happen if the sequence is calculated sequentially
            print(f"Error: Index {idx2} for a_{n} not in calculated set.")
            return {}

        a[n] = a[idx1] + a[idx2]
    return a

